"""Tests for roman.py."""

import pytest
from roman import to_roman, from_roman


class TestToRoman:
    """Tests for to_roman()."""

    def test_one(self):
        assert to_roman(1) == 'I'

    def test_two(self):
        assert to_roman(2) == 'II'

    def test_three(self):
        assert to_roman(3) == 'III'

    def test_four(self):
        assert to_roman(4) == 'IV'

    def test_five(self):
        assert to_roman(5) == 'V'

    def test_nine(self):
        assert to_roman(9) == 'IX'

    def test_ten(self):
        assert to_roman(10) == 'X'

    def test_forty(self):
        assert to_roman(40) == 'XL'

    def test_fifty(self):
        assert to_roman(50) == 'L'

    def test_ninety(self):
        assert to_roman(90) == 'XC'

    def test_hundred(self):
        assert to_roman(100) == 'C'

    def test_four_hundred(self):
        assert to_roman(400) == 'CD'

    def test_five_hundred(self):
        assert to_roman(500) == 'D'

    def test_nine_hundred(self):
        assert to_roman(900) == 'CM'

    def test_thousand(self):
        assert to_roman(1000) == 'M'

    def test_fourteen(self):
        assert to_roman(14) == 'XIV'

    def test_fortytwo(self):
        assert to_roman(42) == 'XLII'

    def test_mcdxliv(self):
        assert to_roman(1444) == 'MCDXLIV'

    def test_max(self):
        assert to_roman(3999) == 'MMMCMXCIX'

    # Boundary values
    def test_boundary_min(self):
        assert to_roman(1) == 'I'

    def test_boundary_max(self):
        assert to_roman(3999) == 'MMMCMXCIX'

    # Out of range
    def test_zero_raises(self):
        with pytest.raises(ValueError):
            to_roman(0)

    def test_negative_raises(self):
        with pytest.raises(ValueError):
            to_roman(-1)

    def test_above_max_raises(self):
        with pytest.raises(ValueError):
            to_roman(4000)

    # Non-integer types
    def test_float_raises(self):
        with pytest.raises(ValueError):
            to_roman(1.5)

    def test_string_raises(self):
        with pytest.raises(ValueError):
            to_roman('1')

    def test_none_raises(self):
        with pytest.raises(ValueError):
            to_roman(None)

    def test_bool_raises(self):
        with pytest.raises(ValueError):
            to_roman(True)

    def test_list_raises(self):
        with pytest.raises(ValueError):
            to_roman([1])


class TestFromRoman:
    """Tests for from_roman()."""

    def test_i(self):
        assert from_roman('I') == 1

    def test_ii(self):
        assert from_roman('II') == 2

    def test_iii(self):
        assert from_roman('III') == 3

    def test_iv(self):
        assert from_roman('IV') == 4

    def test_v(self):
        assert from_roman('V') == 5

    def test_ix(self):
        assert from_roman('IX') == 9

    def test_x(self):
        assert from_roman('X') == 10

    def test_xl(self):
        assert from_roman('XL') == 40

    def test_l(self):
        assert from_roman('L') == 50

    def test_xc(self):
        assert from_roman('XC') == 90

    def test_c(self):
        assert from_roman('C') == 100

    def test_cd(self):
        assert from_roman('CD') == 400

    def test_d(self):
        assert from_roman('D') == 500

    def test_cm(self):
        assert from_roman('CM') == 900

    def test_m(self):
        assert from_roman('M') == 1000

    def test_mmmcmxcix(self):
        assert from_roman('MMMCMXCIX') == 3999

    def test_complex(self):
        assert from_roman('MCDXLIV') == 1444

    # Invalid numerals
    def test_empty_string_raises(self):
        with pytest.raises(ValueError):
            from_roman('')

    def test_iiii_raises(self):
        with pytest.raises(ValueError):
            from_roman('IIII')

    def test_vv_raises(self):
        with pytest.raises(ValueError):
            from_roman('VV')

    def test_ic_raises(self):
        with pytest.raises(ValueError):
            from_roman('IC')

    def test_xm_raises(self):
        with pytest.raises(ValueError):
            from_roman('XM')

    def test_mmmm_raises(self):
        with pytest.raises(ValueError):
            from_roman('MMMM')

    def test_banana_raises(self):
        with pytest.raises(ValueError):
            from_roman('banana')

    def test_non_string_raises(self):
        with pytest.raises(ValueError):
            from_roman(42)

    def test_none_raises(self):
        with pytest.raises(ValueError):
            from_roman(None)

    def test_lowercase_raises(self):
        with pytest.raises(ValueError):
            from_roman('iv')

    def test_invalid_char_raises(self):
        with pytest.raises(ValueError):
            from_roman('J')

    def test_repeated_v_raises(self):
        with pytest.raises(ValueError):
            from_roman('VV')

    def test_repeated_l_raises(self):
        with pytest.raises(ValueError):
            from_roman('LL')

    def test_repeated_d_raises(self):
        with pytest.raises(ValueError):
            from_roman('DD')

    def test_il_raises(self):
        with pytest.raises(ValueError):
            from_roman('IL')

    def test_xs_raises(self):
        with pytest.raises(ValueError):
            from_roman('XS')

    def test_lc_raises(self):
        with pytest.raises(ValueError):
            from_roman('LC')

    def test_cd_valid(self):
        assert from_roman('CD') == 400

    def test_cm_valid(self):
        assert from_roman('CM') == 900

    def test_xl_valid(self):
        assert from_roman('XL') == 40

    def test_ix_valid(self):
        assert from_roman('IX') == 9


class TestRoundTrip:
    """Verify from_roman(to_roman(n)) == n for all n in [1, 3999]."""

    def test_all_values(self):
        for n in range(1, 4000):
            assert from_roman(to_roman(n)) == n, f"Failed for {n}"

    def test_sample_values(self):
        samples = [1, 4, 9, 40, 90, 400, 900, 1000, 1444, 1999, 3999]
        for n in samples:
            assert from_roman(to_roman(n)) == n
